require "sellapp"

client = SellApp::Client.new(base_url: ENV.fetch("SELLAPP_API_BASE_URL"), api_key: ENV.fetch("SELLAPP_API_KEY"), store: ENV.fetch("SELLAPP_STORE"))

result = client.products.batch_create(
  resources: [
    {
      title: "Example product",
      description: "An example product created through the API.",
      visibility: "PUBLIC",
      type: "product"
    }
  ]
)
puts result.inspect

require "sellapp"

client = SellApp::Client.new(base_url: ENV.fetch("SELLAPP_API_BASE_URL"), api_key: ENV.fetch("SELLAPP_API_KEY"), store: ENV.fetch("SELLAPP_STORE"))

result = client.product_variants.batch_create(
  product: 1,
  resources: [
    {
      title: "Default",
      description: "Default product variant.",
      deliverable: {
        types: ["TEXT"],
        data: { serials: ["SERIAL-001"], parsingMode: "NEW_LINE", removeDuplicate: true }
      },
      pricing: { humble: false, price: { price: 1000, currency: "USD" } },
      payment_methods: ["PAYPAL"]
    }
  ]
)
puts result.inspect

require "sellapp"

client = SellApp::Client.new(base_url: ENV.fetch("SELLAPP_API_BASE_URL"), api_key: ENV.fetch("SELLAPP_API_KEY"), store: ENV.fetch("SELLAPP_STORE"))

result = client.orders.search(
  filters: [
    { field: "transaction_id", operator: "contains", value: "pi_3Example" },
    { field: "status", operator: "in", value: ["COMPLETED"] }
  ],
  sort: [{ field: "created_at", direction: "desc" }],
  pagination: { page: 1, limit: 25 }
)
puts result.inspect

require "sellapp"

client = SellApp::Client.new(base_url: ENV.fetch("SELLAPP_API_BASE_URL"), api_key: ENV.fetch("SELLAPP_API_KEY"), store: ENV.fetch("SELLAPP_STORE"))

result = client.coupons.batch_update(
  resources: {
    "1" => { store_wide: false, products: [123], product_variants: [1001, 1002] }
  }
)
puts result.inspect

require "sellapp"

client = SellApp::Client.new(base_url: ENV.fetch("SELLAPP_API_BASE_URL"), api_key: ENV.fetch("SELLAPP_API_KEY"), store: ENV.fetch("SELLAPP_STORE"))

result = client.coupons.v2_batch_update_coupons(
  resources: {
    "1" => { store_wide: false, products: [123], product_variants: [1001, 1002] }
  }
)
puts result.inspect
